"""Complete, judge-ready statements adapted from the supplied Contest 1 sources."""
J,I,S='Junior','Intermediate','Senior'
SPACE='Use spaces between input values. Do not include the paper worksheet’s numbered labels or commas.'
ROUND='Round to the nearest whole number, with exact halves rounded up. Do not put thousands separators in output.'

def spec(y,d):
    constraints=[]
    if y==2007:
        statement='Each data line describes two sets of side lengths. Consider every one-to-one pairing of their sides.'
        inp='Five lines, each containing six positive decimal numbers. The first three describe the first triangle; the final three describe the second. '+SPACE
        if d==J:statement+=' Find the largest number of equal side pairs. Each side can be used only once.';out='One integer from 0 to 3 per input line.'
        else:
            statement+=' The first triangle has vertices ABC and its sides are given in order AB, BC, AC. The second has vertices DEF and its sides are given in order DE, EF, DF. A name such as EFD means A corresponds to E, B to F, and C to D.'
            if d==I:statement+=' Find a correspondence making all three paired side lengths equal.';out='Print the corresponding three-letter name, or NONE if no correspondence makes all sides equal.'
            else:statement+=' First check both sets with the strict triangle inequality: the sum of any two sides must exceed the third. Then find a correspondence for which all three ratios of corresponding side lengths are equal.';out='Print NOT VALID if either set fails the triangle inequality; otherwise print the corresponding three-letter name, or NONE if no proportional correspondence exists.'
            out+=' If several names satisfy the rules, print the alphabetically first name. Print one answer per input line.'
        constraints=['Side lengths are positive decimals, at most 1000000.','Do not reject invalid triangles in the Junior or Intermediate version; only Senior requests validation.']
    elif y==2008:
        statement='A bridge bid b promises b + 6 tricks. Clubs (C) and diamonds (D) score 20 points per contracted trick; hearts (H) and spades (S) score 30. No trump scores 40 for the first contracted trick and 30 for each remaining one. If the contract is made, these contracted points go below the line. Every extra trick scores above the line at 20 points for C/D and 30 for H/S/no trump.'
        if d==J:inp='Five lines: bid, tricks won, suit. The suit is C, D, H, S, or N (no trump). All contracts are made. '+SPACE;out='For each line, print the below-line points and above-line points, separated by one space.'
        else:
            statement+=' If the contract fails, the bidding team scores nothing and its opponent receives above-line points for each missing trick: 50 when the bidding team is not vulnerable, or 100 when vulnerable.'
            if d==I:inp='Five lines: bid, tricks won, suit, vulnerability. Suit T means no trump; vulnerability is V or N. '+SPACE;out='For each line, print below-line and above-line points for the team receiving points. A failed contract therefore prints 0 followed by the penalty.'
            else:
                statement+=' Start both teams at zero, not vulnerable. Add each successful contract to that team’s totals. After printing a line, if a team has reached at least 100 below-line points, reset both below-line totals to zero. The winning team becomes vulnerable and stays vulnerable for the remaining lines. Above-line totals are never reset.'
                inp='Five lines: bidding team (1 or 2), bid, tricks won, suit. Suit T means no trump. '+SPACE;out='After each deal, before any reset, print team 1 below, team 1 above, team 2 below, team 2 above, separated by spaces.'
        constraints=['1 ≤ bid ≤ 7; 0 ≤ tricks won ≤ 13.']
    elif y==2009:
        statement='Golf scores are better when smaller. Report a cumulative score relative to the sum of the par values: use par for zero difference, x under par for a negative difference, and x over par for a positive difference. A hole is won only by a player whose score is strictly lower than every opponent’s score on that hole; ties do not win holes.'
        if d==J:statement+=' The names of scores relative to one hole’s par are: -2 eagle, -1 birdie, 0 par, +1 bogey, +2 double bogey.';inp='Four lines, each containing par and the player’s score. '+SPACE;out='Print each hole’s score name on its own line, then a fifth line giving the four-hole total relative to par.';constraints=['Par is 3, 4, or 5. Scores are positive and differ from par by at most 2.']
        elif d==I:inp='Nine lines, each containing par, player A’s score, and player B’s score. '+SPACE;out='Print five lines: (1) the two cumulative scores, smaller first, separated by a space; (2) the better player’s total relative to par; (3) the other total relative to par; (4) holes won by the better player; (5) the largest combined A+B score on one hole.';constraints=['Par is 3, 4, or 5; scores are positive integers. The cumulative totals are different.']
        else:statement+=' The par values for the nine holes are 3, 4, 5, 4, 4, 4, 5, 3, 4. The median of 36 scores is the average of the 18th and 19th values after sorting.';inp='Nine lines, each containing the scores for A, B, C, D in that order. '+SPACE;out='Print five lines: (1) B’s total relative to par; (2) A’s total relative to par; (3) holes won by the player with the smallest cumulative total; (4) player letters from best to worst, separated by spaces; (5) the median of all 36 scores, as an integer or a number ending in .5.';constraints=['Scores are positive integers. All four cumulative totals are distinct.']
    elif y==2010:
        statement='The Henry fingerprint system assigns weights to fingers 1 through 10: 16, 16, 8, 8, 4, 4, 2, 2, 1, 1. The primary group ratio is (1 + weights of whorls on even-numbered fingers) / (1 + weights of whorls on odd-numbered fingers). Do not reduce this fraction.'
        if d==J:inp='Up to five lines listing the distinct finger numbers with whorls, followed by 0. A line containing only 0 means no whorls. '+SPACE;out='One unreduced ratio per line, written numerator/denominator without spaces.'
        elif d==I:statement+=' The alternative AFCS system uses fingers 1–5 for the right hand and 6–10 for the left. Their weights are 16, 8, 4, 2, 1 on each hand. Its numerator is 1 plus the right-hand whorl weights, and its denominator is 1 plus the left-hand whorl weights.';inp='Up to five lines: system H or A, distinct finger numbers with whorls, then 0. H selects Henry and A selects AFCS. '+SPACE;out='One unreduced ratio per line, written numerator/denominator without spaces.'
        else:statement+=' Reverse the Henry calculation to identify the fingers with whorls. The numerator and denominator are supplied separately, before any reduction.';inp='Up to five lines, each containing the Henry numerator and denominator. '+SPACE;out='For each line print the finger numbers in ascending order, separated by spaces. If there are no whorls, print None.'
        constraints=['Finger numbers are 1–10; ratio components are 1–32.']
    elif y==2011:
        statement='Each contract gives its length in years and total value in millions of dollars. The annual salary is total value divided by contract length. Salary per game is annual salary divided by the number of games in a season. Use the unrounded values in every calculation; round only final answers. '+ROUND
        if d==J:inp='Five lines: contract years and total contract value in millions. '+SPACE;out='Print five lines: count of annual salaries strictly greater than $10 million; mean annual salary in dollars; smallest salary per game for 16 games; largest salary per game for 18 games; mean per-game salary for 16 games minus the mean for 18 games.'
        elif d==I:inp='Ten lines: contract years and total contract value in millions. '+SPACE;out='Print five lines: mean annual salary; largest annual salary followed by its 1-based draft-pick number (separated by a space); range of salaries per game for 16 games; midrange of salaries per game for 18 games; mean per-game salary for 16 games minus the mean for 18 games. Midrange means (minimum + maximum)/2.'
        else:statement+=' A third input value gives guaranteed money in millions. For injury chance p per year, expected contract value is (1 − years × p) × contract value + years × p × guaranteed money. Use p = 0.03 for 16-game seasons and p = 0.03375 for 18-game seasons.';inp='Ten lines: contract years, total contract value in millions, guaranteed money in millions. '+SPACE;out='Print five lines, in dollars: range of per-game salaries for 16 games; midrange of per-game salaries for 18 games; highest entire-contract expected value for 16 games followed by its 1-based pick number; mean entire-contract expected value for 18 games; median annual salary (average of the 5th and 6th sorted annual salaries).'
        constraints=['Contract lengths are 1–10 years; total values are positive and at most 1000 million.','Guaranteed money, when supplied, is between 0 and the contract value.','If a reported maximum is tied, use the lowest pick number.']
    elif y==2012:
        statement='Time codes 1, 2, …, 9, A, B, C, D, E, F, G, H represent half-hour intervals from 9:00 AM to 5:00 PM: 1=9:00 AM, 2=9:30, 9=1:00 PM, A=1:30 PM, …, H=5:00 PM. Hours worked are half the difference between the end and start code positions. A zero-length shift is allowed. Print dollars with a dollar sign and exactly two decimals; round half cents up after summing the complete requested pay.'
        if d==J:statement+=' Locations 1–9 pay $10/hour. Locations 10–19 pay $8/hour for the first 4 hours each day and $12/hour thereafter. Locations 20–29 pay $12/hour for the first 4 hours and $24/hour thereafter.';inp='Four lines: location, start code, end code. '+SPACE;out='Print the four daily pays, then their total on a fifth line.'
        else:
            period='per day' if d==I else 'for the week';limits='5, 6, and 4' if d==I else '30, 40, and 20'
            statement+=f' Locations 100–199 pay $10/hour, then $15/hour beyond the first {5 if d==I else 30} hours {period}. Locations 200–299 pay $7.50/hour, then $15/hour beyond {6 if d==I else 40} hours {period}. Locations 300–399 pay $9.25/hour for the first {4 if d==I else 20} hours {period} and $10.50/hour thereafter. Locations 400–499 pay $13.50/hour on Sunday (day 1) and Saturday (day 7), otherwise $6.75/hour. Locations 500–599 pay $8/hour for the first 6 hours of EACH DAY and $12/hour thereafter.'
            if d==I:inp='Five lines, each with two work-day records. Each record contains location, day number, start code, end code. '+SPACE;out='Print the combined pay for the two days on each input line.'
            else:inp='Five lines. Each contains one location followed by seven start/end code pairs, for Sunday through Saturday. '+SPACE;out='Print the total weekly pay for each line.'
        constraints=['Start and end codes are 1–9 or A–H; start is no later than end.','Day numbers, when supplied, are 1–7.']
    elif y==2013:
        statement='Score a four-letter word on a board with 4 rows and 10 columns, numbered 1–40 in row-major order. Horizontal placements move +1 per letter; vertical placements move +10. Letters score A/E=1, D/R=2, B/M=3, V/Y=4, J/X=8. Assign each square the first matching bonus in this priority order: numbers 3,9,15,… (square % 6 = 3) double the letter; otherwise multiples of 5 triple the letter; otherwise multiples of 7 double the word; otherwise multiples of 8 triple the word. All other squares have no bonus. Sum the modified letter values, then apply the word multipliers.'
        if d==J:inp='First line: four letters separated by spaces. Next five lines: one horizontal starting square. '+SPACE;out='Print the word score for each placement.'
        elif d==I:inp='First line: four letters separated by spaces. Next five lines: starting square and H or V. '+SPACE;out='Print the word score for each placement.'
        else:inp='First line: four letters separated by spaces. Next five lines: three starting-square/direction pairs; each direction is H or V. '+SPACE;out='For each of the five lines, print the maximum score among its three candidate placements. Multiple word multipliers multiply together.'
        constraints=['Words use only A, E, D, R, B, M, V, Y, J, X.','Every placement fits entirely on the board without wrapping a row.']
        if d!=S:constraints+=['A tested placement contains at most one word-multiplier square.']
    elif y==2014:
        if d!=S:
            statement='Travel along cities A, B, C, D, E, F, G, in that order. Adjacent distances in miles are AB=450, BC=140, CD=120, DE=320, EF=250, FG=80. Sum the intervening distances. Travel time is distance/speed and fuel cost is distance × price per gallon / miles per gallon. Round total minutes to the nearest minute (half up), then split into hours and minutes. Round fuel cost to the nearest cent (half up).'
            if d==J:inp='First line: miles per gallon, price per gallon, speed in miles/hour. Next five lines: starting and ending city. '+SPACE
            else:statement+=' Vehicle fuel economy: C=28, M=25, F=22, V=20 miles/gallon. Road speeds: I=65, H=60, M=55, S=45 miles/hour.';inp='Five lines: starting city, ending city, vehicle code, road code, price per gallon. '+SPACE
            out='For each trip print distance, time, and fuel cost separated by spaces, for example 590 09:50 $89.44. Hours and minutes use at least two digits each; minutes are 00–59.'
        else:
            statement='Two travelers drive toward one another. Cities are A B C D E F G H J K, with adjacent distances 450, 140, 125, 365, 250, 160, 380, 235, 320 miles. Each traveler starts at the supplied clock time and speed. Interpret the difference between starting times as the smallest signed difference on a 24-hour clock; for example, 11 PM followed by 2 AM is a 3-hour delay, while 5 PM followed by 3 PM means the second traveler started 2 hours earlier. Find elapsed time from the FIRST traveler’s departure until they meet. Round total minutes half up before formatting.';inp='Five lines: city 1, city 2, hour 1, AM/PM, hour 2, AM/PM, speed 1, speed 2. '+SPACE;out='One elapsed time per line in h:mm format. Hours have no unnecessary leading zero; minutes have exactly two digits.'
        constraints=['Starting city precedes ending city in the route order.','Speeds and fuel economy are positive; prices are positive decimal values.','Senior starting times differ by less than 12 hours, and both travelers depart before they meet.']
    elif y==2015:
        statement='The three permission digits describe owner, group, others, in that order. Each octal digit 0–7 becomes exactly three binary bits, including leading zeroes. Bits 4,2,1 mean read, write, execute, represented by r,w,x; absent permissions are -. Keep a space between each group. Separate the two requested representations with the literal word and.'
        if d==J:inp='Five lines, each with three octal digits separated by spaces.';out='For each line print the binary groups, then and, then the permission groups; for example 101 010 110 and r-x -w- rw-.'
        elif d==I:inp='Five lines. Lines 1–2 contain three octal digits; lines 3–4 contain three 3-bit binary groups; line 5 contains three permission groups, such as r-x rw- rwx.';out='For octal input, print binary and permissions. For binary input, print the three-digit octal string and permissions. For permission input, print the three-digit octal string and binary. Use and between forms, as in 415 and r-- --x r-x.'
        else:statement+=' A fourth digit comes BEFORE the three ordinary digits: 0=no special permission, 1=owner, 2=group, 4=others. Only if the affected class already has x, change that x to s for owner/group or t for others. This ACSL mapping is part of the problem; do not substitute a different operating-system convention.';inp='Five lines: special digit, owner digit, group digit, others digit, separated by spaces.';out='Print the ordinary nine binary bits and the modified permission groups, separated by and. Do not print the special digit’s binary bits.'
        constraints=['Octal permission digits are 0–7.','Senior special digit is 0, 1, 2, or 4.']
    elif y==2016:
        statement='Given the opponent’s lead card and the dealer’s five-card hand, choose the dealer’s move. Follow the lead suit if possible. Among cards of that suit, choose the lowest rank strictly greater than the lead rank; if none wins, choose the lowest rank of that suit.'
        if d==J:statement+=' If the dealer has no card of the lead suit, output NONE. Ranks are 1–9.';inp='Five lines. Each contains six rank/suit pairs: the lead card, then five dealer cards. For example, 5 D 2 D 6 H 9 D 9 S 6 H.';out='One rank and suit separated by a space per line, or NONE.'
        else:
            statement+=' Ranks, lowest first, are A 2 3 4 5 6 7 8 9 T J Q K. If the dealer cannot follow suit, choose the lowest-ranked card from the entire hand.'
            if d==S:statement+=' Break equal-rank ties by suit order C, D, H, S.'
            else:statement+=' In the no-matching-suit case, the lowest rank is unique.'
            inp='Five lines: lead card and five dealer cards, each a two-character rank/suit token, such as 5D 2D 6H 9D TD 6S.';out='One two-character chosen card per line, with no space inside the card.'
        constraints=['Suits are C, D, H, S.','Cards in different deals are independent.']
    elif y==2017:
        statement='Simulate the game until a card makes the running total exceed 99. The player who plays that card loses. Check for a loss immediately after applying a card; do not draw another card after the game ends. Unused supplied cards are ignored.'
        if d==J:statement+=' Cards are 0–9. The player plays cards in arrival order (a queue). A 9 leaves the total unchanged; a 4 subtracts 10; a 0 adds 11 if that stays at most 99, otherwise adds 1. Other cards add their face value.';inp='Five lines: initial total, three cards initially held by the player, then seven cards alternating player draw, dealer play, player draw, dealer play, and so on. The player moves first.';out='For each line print the final total and the winner: player or dealer, separated by a space.'
        elif d==I:statement+=' Ranks 2–9,T,J,Q,K,A have face values 2–14. Play the highest FACE VALUE in the player’s hand, even when that card has a special effect. A 9 passes; T subtracts 10; A adds 14 if the result stays at most 99, otherwise adds 1. Other cards add their face value.';inp='Five lines: initial total, three player cards, then seven tokens alternating player draw and dealer play. The player moves first.';out='For each line print the final total and winner, player or dealer, separated by a space.'
        else:statement+=' Ranks 2–9,T,J,Q,K,A have face values 2–14. Each player holds five cards and plays the middle (third) card when sorted by FACE VALUE. A 9 passes; T subtracts 10; a 7 adds 7 if the result is at most 99, otherwise 1. A adds 14. After applying the card, add 5 for every border 33/34, 55/56, or 77/78 crossed in either direction by that card’s change. Determine crossings from the totals before and just after the card effect; do not count crossings caused by the bonus itself.';inp='First line: five initial cards for Player #1 and five for Player #2. Next five lines: initial total followed by ten draw cards, alternating Player #1 and Player #2. Reset both hands to the first line before each game. Player #1 always moves first.';out='For each game print final total followed by Player #1 or Player #2, naming the winner, for example 109 Player #1.'
        constraints=['Initial totals are 0–99.','Each supplied game is guaranteed to produce a winner before the necessary cards run out.']
    elif y==2018:
        if d==J:statement='Answer five different questions about decimal integers: line 1 asks for the number of digits; line 2 for the digit sum; line 3 for the sum at odd 1-based positions from the LEFT; line 4 for the count of digit 4; line 5 for the middle digit. For an even length choose the left of the two middle digits.';inp='Exactly five positive decimal integers, one per line.';out='Print the five answers, one per line.'
        else:statement='Read each integer as a decimal digit string; leading zeroes inside a selected group contribute normally.'
        if d==I:statement+=' Starting at every position where n digits remain, take a consecutive length-n window. Windows overlap. Add the numeric values of all windows.';inp='Five lines, each containing a positive decimal integer and a window length n.';out='Print the sum of the overlapping groups for each line.'
        if d==S:statement+=' Split left to right into NON-overlapping groups of n digits. Pad the final short group with trailing zeroes to reach n digits, then add all group values.';inp='Five lines, each containing a positive decimal integer and a group length n.';out='Print the sum of the padded groups for each line.'
        constraints=['Integers have 1–50 digits and no leading zero.','Intermediate: 1 ≤ n ≤ number of digits. Senior: 1 ≤ n ≤ 50; n may exceed the number’s length.','Use arithmetic that preserves all digits.']
    elif y==2019:
        statement='Positions are counted from the RIGHT starting at 1. Let x be the original digit at position P. All changes are based on the original digits, not on digits already changed.'
        if d==J:statement+=' If x is 0–4, replace it by the units digit of x+D. If x is 5–9, replace it by the LEFTMOST digit of |x−D| (the value 0 has digit 0). Replace every digit to its right by 0; leave digits to the left unchanged.';inp='Five lines: positive integer N, position P, positive transition integer D.'
        elif d==I:statement+=' Replace every digit to the left of x with the units digit of its sum with x. Leave x unchanged. Replace every digit to its right with its absolute difference from x.';inp='Five lines: positive integer N and position P.'
        else:statement+=' Replace every digit to the left of x with its full sum with x, which can have two digits. Replace x with the number of DISTINCT prime factors of the original N. The number 1 has zero prime factors. Replace every digit to the right with its absolute difference from x. Concatenate the resulting pieces without separators.';inp='Five lines: positive integer N and position P.'
        out='One transformed digit string per line, without spaces.';constraints=['1 ≤ N < 10^15; P is a valid digit position.','Junior and Intermediate inputs do not produce a leading zero. Junior D is positive and at most 10^9.']
    elif y==2020:
        statement='Fill a triangle row by row: row 1 has one term, row 2 two, and row r has r. The untransformed sequence starts at s and increases by d for every position.'
        if d==J:statement+=' Before displaying each term, repeatedly add its decimal digits until one digit remains. Do not use a displayed digit as the starting value for the next term.';inp='Five lines: decimal s, d, r.';out='For each line print the sum of the r single digits displayed in row r.';constraints=['1 ≤ s,d,r < 100000.']
        elif d==I:statement+=' Write every full term in octal. Do NOT repeatedly reduce terms to one digit. Add all the individual octal digits appearing on row r.';inp='Five lines: octal s, octal d, decimal r.';out='For each line print the sum of the row’s octal digits as a decimal integer.';constraints=['1 ≤ s,d,r < 262144; s and d use only digits 0–7.']
        else:statement+=' Write terms in hexadecimal. First add the full numeric values on row r. Then repeatedly sum the hexadecimal digits of THAT SUM until one hexadecimal digit remains.';inp='Five lines: hexadecimal s, hexadecimal d, decimal r.';out='One uppercase hexadecimal digit per line.';constraints=['1 ≤ s,d,r < 16777216; s and d use 0–9 and uppercase A–F.']
    elif y==2021:
        statement='The five Fibonacci clock squares have weights 1, 1, 2, 3, 5, in that order (lower 1×1, upper 1×1, 2×2, 3×3, 5×5). White (W) contributes nothing.'
        if d!=S:statement+=' Red (R) contributes its weight to hours, green (G) to minutes, and blue (B) to BOTH hours and minutes. Multiply the minute-weight sum by 5.';inp='Five lines, each containing five color letters separated by spaces.';out='One zero-padded hh:mm time per line.'
        if d==I:statement+=' Carry 60 minutes to one hour, and wrap hours modulo 12.'
        if d==S:statement+=' Red (R) contributes to hours; green (G) to minutes; blue (B) to seconds. Yellow (Y) contributes to hours AND minutes, magenta (M) to hours AND seconds, cyan (C) to minutes AND seconds. Multiply both minute- and second-weight sums by 5. Carry seconds into minutes and minutes into hours, then wrap hours modulo 12.';inp='Five lines, each containing one five-character string using R,G,B,C,M,Y,W.';out='One zero-padded hh:mm:ss time per line.'
        constraints=['Each data set contains exactly five squares.']
        if d==J:constraints+=['Junior inputs already represent hours 0–11 and minutes 0–55 without carrying.']
    elif y==2022:
        statement='Generate n consecutive integers starting with s, inclusive. The starting value is written in base b. Subsequent values also use base b, with no leading zeroes. Count digits in these base-b representations, but report the requested answer in decimal.'
        if d==J:statement+=' Find the sum of all digit VALUES across the generated numbers.'
        elif d==I:statement+=' Count occurrences of the largest allowed digit, b−1, across the generated numbers, even if that digit does not appear at all.'
        else:statement+=' Count occurrences of each digit across the generated numbers. Return the largest occurrence COUNT, not the identity of the digit. For bases over 10, A=10, B=11, …, F=15.'
        inp='One or more lines, each containing n, decimal base b, and starting digit string s. There is no test-count prefix.';out='One decimal answer for each input line.';constraints=[f'1 ≤ n ≤ 100000; 2 ≤ b ≤ {16 if d==S else 9}.','s is positive, valid in base b, and has at most 16 digits.','Generated numbers may grow beyond 16 digits; do not overflow a fixed-width integer.']
    elif y==2023:
        statement='Four rows begin with the four digits of originalRows, padding with leading zeroes when needed. A two-digit tile can be reversed. It matches a row when one end equals the row’s last digit; append the tile so the matching end touches the row. Start checking at row 1. After a placement, start the next search at the row AFTER the row just used, wrapping from row 4 to row 1. If the placed tile is a double, the next placement MUST be on that same row; this lock remains until a non-double is placed there.'
        if d==I:statement+=' Process tiles once, in input order. For each tile, try rows in the prescribed cyclic order, or only the locked row. If it cannot be placed, discard it without changing the next-search position or lock. Add the two digits of every discarded tile.';inp='Two lines: originalRows, then a space-separated list of tiles.';out='The sum of all individual digits on discarded tiles.';constraints=['originalRows contains four digits 1–9.','The hand has 1–50 tiles; each tile has two digits from 1–9.']
        else:statement+=' On each turn, scan the hand from its FIRST tile, trying each against rows in the prescribed order. Place the first tile that fits and restart scanning the remaining hand from the beginning. If no hand tile fits, draw tiles one at a time, appending them to the hand, until one can be placed. Stop as soon as the hand is empty, even if the draw pile is not; also stop when no hand tile fits and the draw pile is empty. Sum the individual digits remaining in the HAND, excluding undrawn tiles.';inp='Three lines: originalRows, hand tiles separated by spaces, draw-pile tiles separated by spaces. An empty third line means no draw tiles. A token 0 is the tile 00, not an empty draw pile.';out='The sum of all individual digits on tiles left in the hand.';constraints=['0 ≤ originalRows ≤ 9999; use leading zero padding to obtain four row digits.','Each tile is 0–99; one-digit tiles are padded with a leading zero.','The hand has 1–50 tiles; the draw pile has 0–50 tiles.']
    else:
        statement='ACSL Rings awards points for ring colors: aqua A=1, red R=1, orange O=3, green G=3, black B=6.'
        if d==J:inp='Two lines, each a string of color letters representing one player’s tosses.';out='The two scores in descending order, separated by a space.';constraints=['Each string has 1–100 letters from A,R,O,G,B.']
        else:
            statement+=' A toss through an overlap scores the sum of its two colors PLUS 1. The permitted overlapping pairs are AO, OB, BG, GR.'
            if d==I:inp='Three lines, one per player. Tosses are separated by single spaces; each token is A,R,O,G,B,AO,OB,BG,or GR.';out='The three scores in descending order, separated by single spaces.';constraints=['Each line is nonempty and has at most 100 characters.']
            else:statement+=' The overlap letters may also be reversed (OA, BO, GB, RG). A + at the END of a token adds 2 long-distance bonus points for that toss. Sort players by descending score; for equal scores, the player with FEWER tosses comes first. The input guarantees no remaining ties.';inp='First line: number of players n. Next n nonempty lines: one player’s toss tokens separated by spaces.';out='One line of playerNumber-score tokens, separated by spaces, in ranked order. Player numbers start at 1.';constraints=['1 ≤ n ≤ 100; each player has 1–100 tosses.','No two players have both the same score and same toss count.']
    return dict(statement=statement,inputSpec=inp,outputSpec=out,constraints=constraints)
